/**
 * The backend side of filtering: the repository narrows both the pages and the
 * count, still refuses oversized pages, and still records every query.
 */
class CustomerRepositoryFilterTest {

    private QueryLog queryLog;
    private CustomerRepository repository;

    @BeforeEach
    void createRepository() {
        queryLog = new QueryLog();
        repository = new CustomerRepository(queryLog);
    }

    @Test
    void countsOnlyMatchingCustomers() {
        assertEquals(500, repository.count());
        assertEquals(15, repository.count(CustomerFilter.byName("vir")));
        assertEquals(167, repository.count(CustomerFilter.byStatus(CustomerStatus.ACTIVE)));
        assertEquals(10, repository.count(
                new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED))));
        assertEquals(0, repository.count(CustomerFilter.byName("zzz")));
    }

    @Test
    void matchingIgnoresCaseAndAccentsBothWays() {
        assertEquals(15, repository.count(CustomerFilter.byName("mäkinen")));
        assertEquals(15, repository.count(CustomerFilter.byName("makinen")));
        assertEquals(15, repository.count(CustomerFilter.byName("MAKINEN")));
        assertEquals(12, repository.count(CustomerFilter.byName("josephine")));
        assertEquals(12, repository.count(CustomerFilter.byName("Joséphine")));
    }

    @Test
    void everyNameTermHasToMatchEitherName() {
        assertEquals(2, repository.count(CustomerFilter.byName("ada aal")));
        assertEquals(2, repository.count(CustomerFilter.byName(" aal   ada ")));
        assertEquals(0, repository.count(CustomerFilter.byName("ada virtanen")));
        assertEquals(500, repository.count(CustomerFilter.byName("   ")));
    }

    @Test
    void pagesTheMatchingCustomers() {
        CustomerFilter filter = CustomerFilter.byName("vir");
        List<CustomerSort> byId = List.of(new CustomerSort("id", true));

        List<Customer> firstPage = repository.findAll(0, 10, byId, filter);
        List<Customer> secondPage = repository.findAll(10, 10, byId, filter);

        assertEquals(10, firstPage.size());
        assertEquals(5, secondPage.size());
        assertTrue(firstPage.stream().allMatch(filter::matches));
        assertTrue(secondPage.stream().allMatch(filter::matches));
        assertTrue(firstPage.getFirst().id() < secondPage.getFirst().id());
    }

    @Test
    void sortsTheMatchingCustomersInTheBackend() {
        CustomerFilter filter = CustomerFilter.byName("vir");

        assertEquals("Beatriz", repository
                .findAll(0, 1, List.of(new CustomerSort("firstName", true)), filter)
                .getFirst().firstName());
        assertEquals("Wilma", repository
                .findAll(0, 1, List.of(new CustomerSort("firstName", false)), filter)
                .getFirst().firstName());
    }

