@@ -0,0 +1,117 @@
+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The criteria a customer has to satisfy to be part of a result set.
+ *
+ * <p>A filter has two independent parts, and a customer has to satisfy both:
+ *
+ * <ul>
+ * <li><b>Name.</b> The text is split on whitespace into terms, and every term
+ * has to occur in the customer's first or last name. Matching ignores case and
+ * accents in both directions, so {@code makinen} and {@code MÄKINEN} both match
+ * {@code Mäkinen}. Blank text matches every customer.
+ * <li><b>Status.</b> An empty selection matches every customer; otherwise the
+ * customer's status has to be one of the selected ones.
+ * </ul>
+ *
+ * <p>The type is a value: two filters with the same name text and the same
+ * statuses are equal, which is what lets the UI recognise a filter it has
+ * already counted.
+ *
+ * @param name     the raw name text, as typed; never {@code null}
+ * @param statuses the accepted statuses, empty for "any"; never {@code null}
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) implements Serializable {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** A filter on the name only. */
+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** A filter on the statuses only. */
+    public static CustomerFilter byStatus(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+
+    /** {@code true} when this filter matches every customer. */
+    public boolean isEmpty() {
+        return statuses.isEmpty() && nameTerms().isEmpty();
+    }
+
+    /**
+     * The name terms to look for, normalised for matching: lower case, accents
+     * removed, insignificant whitespace gone.
+     */
+    public List<String> nameTerms() {
+        List<String> terms = new ArrayList<>();
+        for (String term : WHITESPACE.split(name.strip())) {
+            if (!term.isEmpty()) {
+                terms.add(normalize(term));
+            }
+        }
+        return List.copyOf(terms);
+    }
+
+    /**
+     * Returns this filter as a predicate. The name terms are normalised once
+     * up front, so the predicate is cheap to apply to a whole data set.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> accepted = statuses;
+        return customer -> {
+            if (!accepted.isEmpty() && !accepted.contains(customer.status())) {
+                return false;
+            }
+            if (terms.isEmpty()) {
+                return true;
+            }
+            String firstName = normalize(customer.firstName());
+            String lastName = normalize(customer.lastName());
+            for (String term : terms) {
+                if (!firstName.contains(term) && !lastName.contains(term)) {
+                    return false;
+                }
+            }
+            return true;
+        };
+    }
+
+    /** {@code true} when the given customer satisfies this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    /**
+     * Folds a string down to what matching cares about: no case, no accents.
+     * {@code Joséphine} and {@code JOSEPHINE} both become {@code josephine}.
+     */
+    public static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
