+
+/**
+ * The same view in a real browser, for the things a browserless test cannot
+ * see: what the address bar says, and what typing costs the backend.
+ *
+ * <p>Named {@code ...IT} so that {@code mvn test} stays browserless and fast.
+ * Run it with {@code mvn -o test -Dtest=CustomerListViewBrowserIT}.
+ */
+@SpringBootTest(classes = Application.class,
+        webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
