+
+    @AfterAll
+    static void closeBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @BeforeEach
+    void openBrowserPage() {
+        page = browser.newPage();
+        page.setDefaultTimeout(15000);
+    }
+
+    @AfterEach
+    void closeBrowserPage() {
+        page.close();
+    }
+
+    @Test
+    void theListLoadsUnfiltered() {
+        open("/");
+
+        assertSummary("Showing 500 of 500");
+        assertEquals("/", path());
+    }
+
+    @Test
+    void typingNarrowsTheListAndUpdatesTheAddressBar() {
+        open("/");
+        int historyLength = historyLength();
+        queryLog.clear();
+
+        type("virtanen");
+
+        assertSummary("Showing 15 of 500");
+        assertEquals("/?name=virtanen", pathWithQuery());
+        assertEquals(historyLength, historyLength(),
+                "Typing must not push history entries");
+
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing nine letters ran " + queryLog.countQueries().size()
+                        + " count queries: " + queryLog.countQueries());
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing nine letters ran " + queryLog.pageQueries().size()
+                        + " page queries: " + queryLog.pageQueries());
+        assertTrue(queryLog.countQueries().contains(15),
+                "The matching count must come from a count query: " + queryLog.countQueries());
+    }
+
+    @Test
+    void selectingStatusesShowsUpInTheAddressBar() {
+        open("/?name=vir");
+
+        statusField().selectItems("ACTIVE", "CLOSED");
+        assertSummary("Showing 10 of 500");
+        assertEquals("/?name=vir&status=ACTIVE,CLOSED", pathWithQuery());
+    }
+
+    @Test
+    void aFilteredUrlOpensFiltered() {
+        open("/?name=vir&status=ACTIVE,CLOSED");
+
+        assertSummary("Showing 10 of 500");
+        PlaywrightAssertions.assertThat(nameInput()).hasValue("vir");
+        assertEquals(List.of("ACTIVE", "CLOSED"), statusField().getSelectedItems());
+        PlaywrightAssertions.assertThat(page.locator("vaadin-grid-cell-content")
+                .filter(new Locator.FilterOptions().setHasText("Virtanen")).first()).isVisible();
+    }
+
+    @Test
+    void anEncodedNameInTheUrlIsDecoded() {
+        open("/?name=m%C3%A4kinen");
+
+        assertSummary("Showing 15 of 500");
+        PlaywrightAssertions.assertThat(nameInput()).hasValue("m\u00e4kinen");
+    }
+
+    @Test
+    void clearingTheFilterEmptiesTheAddressBar() {
+        open("/?name=vir&status=ACTIVE");
+        assertSummary("Showing 5 of 500");
+
+        statusField().deselectItems("ACTIVE");
+        assertSummary("Showing 15 of 500");
+
+        nameInput().fill("");
+        nameInput().press("Enter");
+        assertSummary("Showing 500 of 500");
+        assertEquals("/", pathWithQuery());
+    }
+
+    // --- Helpers -------------------------------------------------------------
+
+    private void open(String location) {
+        page.navigate("http://localhost:" + port + location);
+        page.waitForFunction(AbstractBasePlaywrightIT.WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    private void type(String text) {
+        nameInput().click();
+        nameInput().pressSequentially(text, new Locator.PressSequentiallyOptions().setDelay(40));
+    }
+
+    private Locator nameInput() {
+        return page.locator("vaadin-text-field input");
+    }
+
+    private MultiSelectComboBoxElement statusField() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private void assertSummary(String expected) {
+        PlaywrightAssertions.assertThat(page.locator("#customer-count")).hasText(expected);
+    }
+
+    private String path() {
+        return (String) page.evaluate("() => window.location.pathname");
+    }
+
+    private String pathWithQuery() {
+        return (String) page.evaluate("() => window.location.pathname + window.location.search");
+    }
+
+    private int historyLength() {
+        return (int) page.evaluate("() => window.history.length");
+    }
+}
